package cn.bidcheck.verification.engine;

import org.junit.jupiter.api.Test;
import java.util.*;
import static cn.bidcheck.verification.engine.VerificationTypes.*;
import static cn.bidcheck.verification.engine.VerificationEngineTest.*;
import static org.junit.jupiter.api.Assertions.*;

class VerificationBindingTest {
    Rule numeric(String expected,String unit,String operator){return new Rule("r","金额要求","NUMBER","","price",operator,expected,unit,cn.bidcheck.compat.Java8Api.mapOf(),"报价不少于100万元","",cn.bidcheck.compat.Java8Api.listOf());}
    @Test void numericThresholdUnitAndOperatorAreOneGroundedConstraint(){assertNull(RequirementGrounding.issue(numeric("100","万元",">=")));assertNotNull(RequirementGrounding.issue(numeric("100","元",">=")));assertNotNull(RequirementGrounding.issue(numeric("1","元",">=")));assertNotNull(RequirementGrounding.issue(numeric("100","万元","<=")));}
    @Test void socialMonthCountCannotBeLowered(){Rule good=new Rule("r","社保","MONTHS","甲","","","","",cn.bidcheck.compat.Java8Api.mapOf("count", 3, "earliestMonth", "2024-12"),"2024年12月起任意连续三个月社保","",cn.bidcheck.compat.Java8Api.listOf());assertNull(RequirementGrounding.issue(good));Rule bad=new Rule(good.id(),good.description(),good.predicate(),good.subject(),good.field(),good.operator(),good.expected(),good.unit(),cn.bidcheck.compat.Java8Api.mapOf("count", 1, "earliestMonth", "2024-12"),good.sourceQuote(),"",cn.bidcheck.compat.Java8Api.listOf());assertNotNull(RequirementGrounding.issue(bad));}
    @Test void explicitPopulationSubsetIsNotComplete(){assertFalse(RequirementGrounding.completeSubjects("甲公司、乙公司、丙公司均须提交承诺",cn.bidcheck.compat.Java8Api.listOf("甲公司", "乙公司")));assertTrue(RequirementGrounding.completeSubjects("甲公司、乙公司、丙公司均须提交承诺",cn.bidcheck.compat.Java8Api.listOf("甲公司", "乙公司", "丙公司")));}
    @Test void conjunctionDoesNotDisappearInsideOneSourceQuote(){Rule r=new Rule("r","承诺书","DECLARATION","","","","承诺书","",cn.bidcheck.compat.Java8Api.mapOf(),"提交承诺书且具备一级资质","",cn.bidcheck.compat.Java8Api.listOf());assertFalse(RequirementCoverage.issues(r.sourceQuote(),cn.bidcheck.compat.Java8Api.listOf(r)).isEmpty());}
    @Test void contractAmountUnitCannotBeInvented(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("测试合同合同总价：100元，不含税。")));Fact f=fact("CONTRACT","测试合同","","测试合同","","",cn.bidcheck.compat.Java8Api.mapOf("contractName", "测试合同", "amount", "100", "unit", "万元", "amountBasis", "合同总价", "taxBasis", "不含税"),c);assertEquals("CONTRACT_AMOUNT_UNIT_UNPROVEN",new ProofVerifier().issue(f,c.byId));}
    @Test void contractTaxCannotInvertIncludedAndExcluded(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("测试合同不含税合同总价：100万元。")));Fact f=fact("CONTRACT","测试合同","","测试合同","","",cn.bidcheck.compat.Java8Api.mapOf("contractName", "测试合同", "amount", "100", "unit", "万元", "amountBasis", "合同总价", "taxBasis", "含税"),c);assertEquals("CONTRACT_TAX_BASIS_UNPROVEN",new ProofVerifier().issue(f,c.byId));}
    @Test void sameAmountElsewhereCannotLendUnit(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("报价：100元；注册资本：100万元")));Fact f=fact("NUMBER","本项目","price","100","万元","报价",cn.bidcheck.compat.Java8Api.mapOf(),c);assertEquals("UNIT_BINDING_INVALID",new ProofVerifier().issue(f,c.byId));}
    @Test void otherPersonDateDoesNotBecomeRequestedPersonDate(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("姓名：乙某，有效期2024年1月1日至2027年1月1日")));Fact f=fact("DATE_RANGE","甲某","","有效期","","",cn.bidcheck.compat.Java8Api.mapOf("field", "有效期", "start", "2024-01-01", "end", "2027-01-01"),c);assertEquals("DATE_FIELD_BINDING_INVALID",new ProofVerifier().issue(f,c.byId));}
    @Test void adjacentCertificatesCannotMergeSubjectsAndGrade(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("姓名：甲某\n二级证书\n姓名：乙某\n一级证书 有效期2024年1月1日至2027年1月1日")));Fact f=fact("CERTIFICATE","甲某","","甲某","","",cn.bidcheck.compat.Java8Api.mapOf("grade", "一级", "start", "2024-01-01", "end", "2027-01-01"),c);assertEquals("CERTIFICATE_SUBJECT_FIELD_BINDING_INVALID",new ProofVerifier().issue(f,c.byId));}
    @Test void futureSubmissionCannotBeClippedIntoPresentMaterial(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("本公司将在中标后提交安全生产许可证，当前尚未将相关材料正式提交。本条只说明将来的安排与责任，不能认定现已附有证书。")));Fact f=fact("MATERIAL","","","安全生产许可证","","",cn.bidcheck.compat.Java8Api.mapOf(),c);assertEquals("FUTURE_SUBMISSION_NOT_PRESENT",new ProofVerifier().issue(f,c.byId));}
    @Test void unresolvedHistoricalAmountCannotPassCurrentPrice(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("历史合同总价：100万元")));Fact base=fact("NUMBER","","price","100","万元","总价",cn.bidcheck.compat.Java8Api.mapOf(),c);Fact f=new Fact(base.id(),base.kind(),base.subject(),base.field(),base.rawValue(),base.value(),base.unit(),base.basis(),"UNRESOLVED",base.sourceIds(),base.attributes());assertEquals("UNDETERMINED",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(f),c,cn.bidcheck.compat.Java8Api.mapOf()).evaluate(numeric("1","万元",">=")).status());}
    @Test void anotherObligationsSealCannotSatisfyRequestedDocument(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("甲公司授权书盖章位置")));Map<String,Object> observation=linked("id","v","obligationId","投标函","documentId","bid","location",1,"locationType","PAGE","imageHash","img","type","SEAL","observedValue","甲公司","readability","CLEAR","sourceBbox",cn.bidcheck.compat.Java8Api.listOf(1, 1, 20, 20),"source",cn.bidcheck.compat.Java8Api.mapOf("documentHash", "sha", "renderedSha256", "img"));Rule r=new Rule("授权书","甲公司授权书盖章","VISUAL","甲公司","seal","","","",cn.bidcheck.compat.Java8Api.mapOf(),"甲公司授权书盖章","",cn.bidcheck.compat.Java8Api.listOf());assertEquals("UNDETERMINED",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(),c,cn.bidcheck.compat.Java8Api.mapOf("visualObservations", cn.bidcheck.compat.Java8Api.listOf(observation))).evaluate(r).status());}
    @Test void contractRuleCannotDiscardConstructionCostBasisOrOriginalUnit(){String quote="建安工程费不少于200万元";Rule missing=new Rule("r","合同","CONTRACT","","","","","万元",cn.bidcheck.compat.Java8Api.mapOf("amountMinimum", 200),quote,"",cn.bidcheck.compat.Java8Api.listOf());assertNotNull(RequirementGrounding.issue(missing));Rule wrongUnit=new Rule("r","合同","CONTRACT","","","","","元",cn.bidcheck.compat.Java8Api.mapOf("amountMinimum", 200, "amountBasis", "建安工程费"),quote,"",cn.bidcheck.compat.Java8Api.listOf());assertNotNull(RequirementGrounding.issue(wrongUnit));Rule good=new Rule("r","合同","CONTRACT","","","","","万元",cn.bidcheck.compat.Java8Api.mapOf("amountMinimum", 200, "amountBasis", "建安工程费"),quote,"",cn.bidcheck.compat.Java8Api.listOf());assertNull(RequirementGrounding.issue(good));}
    @Test void certificateGradeCannotDisappearFromCompiledRule(){Rule r=new Rule("r","证书","CERTIFICATE","甲","","","","",cn.bidcheck.compat.Java8Api.mapOf(),"须具有一级注册证书","",cn.bidcheck.compat.Java8Api.listOf());assertNotNull(RequirementGrounding.issue(r));}
    @Test void dayTenIsNotDayOne(){assertFalse(ProofVerifier.datePresent("2025-01-10","2025-01-01"));assertFalse(ProofVerifier.datePresent("2025年1月10日","2025-01-01"));assertTrue(ProofVerifier.datePresent("2025年1月1日","2025-01-01"));}
    @Test void commaSeparatedOtherAmountCannotLendUnitsOrTax(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("报价：100元，注册资本：100万元；不含税报价：100元，含税注册资本：100万元")));Fact f=fact("NUMBER","","price","100","万元","报价",cn.bidcheck.compat.Java8Api.mapOf(),c);assertEquals("UNIT_BINDING_INVALID",new ProofVerifier().issue(f,c.byId));assertFalse(ProofVerifier.taxBound("不含税报价：100元，含税注册资本：100万元","报价","100","含税"));}
    @Test void socialMonthsFromDifferentPeopleCannotBeCombined(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("姓名：甲某；社保月份2026-01\n姓名：乙某；社保月份2026-02、2026-03")));Fact f=fact("MONTHS","甲某","","甲某","","",cn.bidcheck.compat.Java8Api.mapOf("person", "甲某", "months", cn.bidcheck.compat.Java8Api.listOf("2026-01", "2026-02", "2026-03")),c);assertEquals("MONTH_ROW_UNPROVEN",new ProofVerifier().issue(f,c.byId));}
    @Test void expiredAndRenewedCertificateIsConflictNotDenial(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("甲某注册证书续期资料，证书编号：R001；旧证注册有效期2020年1月1日至2024年1月1日；新证注册有效期2024年1月1日至2027年1月1日")));Fact old=fact("CERTIFICATE","甲某","","旧证","","",cn.bidcheck.compat.Java8Api.mapOf("category", "注册证书", "number", "R001", "numberField", "证书编号", "validityField", "注册有效期", "start", "2020-01-01", "end", "2024-01-01"),c),fresh=fact("CERTIFICATE","甲某","","新证","","",cn.bidcheck.compat.Java8Api.mapOf("category", "注册证书", "number", "R001", "numberField", "证书编号", "validityField", "注册有效期", "start", "2024-01-01", "end", "2027-01-01"),c);Map<String,Object> context=cn.bidcheck.compat.Java8Api.mapOf("referenceDate", "2025-08-01", "referenceDateSource", "t", "referenceDateSourceVerified", true, "referenceDateEvidence", cn.bidcheck.compat.Java8Api.mapOf("documentId", "t", "quote", "投标截止2025年8月1日", "confirmation", "USER_SELECTED_VERSION"));Rule r=rule("VALIDITY","甲某","注册有效期","",cn.bidcheck.compat.Java8Api.mapOf("category", "注册证书", "validityField", "注册有效期"));Decision d=new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(old, fresh),c,context).evaluate(r);assertEquals("UNDETERMINED",d.status());assertEquals("CERTIFICATE_VERSION_REQUIRED",d.gaps().get(0).code());assertEquals("FAIL",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(old),c,context).evaluate(r).status());assertEquals("PASS",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(fresh),c,context).evaluate(r).status());}
    @Test void anotherCertificateCategoryDoesNotDenySelectedCategory(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("甲某多证照，旧A证安全证书编号：A001，有效期2020年1月1日至2024年1月1日；注册证书编号：R001，有效期2024年1月1日至2027年1月1日")));Fact old=fact("CERTIFICATE","甲某","","旧A证","","",cn.bidcheck.compat.Java8Api.mapOf("category", "安全证书", "number", "A001", "numberField", "安全证书编号", "validityField", "有效期", "start", "2020-01-01", "end", "2024-01-01"),c),fresh=fact("CERTIFICATE","甲某","","注册证","","",cn.bidcheck.compat.Java8Api.mapOf("category", "注册证书", "number", "R001", "numberField", "注册证书编号", "validityField", "有效期", "start", "2024-01-01", "end", "2027-01-01"),c);Map<String,Object> ctx=cn.bidcheck.compat.Java8Api.mapOf("referenceDate", "2025-08-01", "referenceDateSource", "t", "referenceDateSourceVerified", true, "referenceDateEvidence", cn.bidcheck.compat.Java8Api.mapOf("documentId", "t", "quote", "投标截止2025年8月1日", "confirmation", "USER_SELECTED_VERSION"));assertEquals("PASS",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(old, fresh),c,ctx).evaluate(rule("VALIDITY","甲某","有效期","",cn.bidcheck.compat.Java8Api.mapOf("category", "注册证书", "validityField", "有效期"))).status());assertEquals("UNDETERMINED",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(old, fresh),c,ctx).evaluate(rule("VALIDITY","甲某","certificateExpiry","",cn.bidcheck.compat.Java8Api.mapOf())).status());}
    @Test void visualRoleResolvesConcreteSubjectAndDoesNotAcceptLiteralRole(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("本项目授权书\n甲公司角色为投标人，授权书盖章位置")));Fact binding=fact("RELATION","甲公司","角色","投标人","","",cn.bidcheck.compat.Java8Api.mapOf("object", "投标人"),c);Rule r=new Rule("r","投标人授权书盖章","VISUAL","投标人","seal","","","",cn.bidcheck.compat.Java8Api.mapOf("documentType", "授权书"),"投标人盖章","",cn.bidcheck.compat.Java8Api.listOf());Map<String,Object> observed=linked("id","v","obligationId","r","documentId","bid","location",1,"locationType","PAGE","imageHash","img","type","SEAL","observedValue","甲公司","readability","CLEAR","sourceBbox",cn.bidcheck.compat.Java8Api.listOf(1, 1, 20, 20),"source",cn.bidcheck.compat.Java8Api.mapOf("documentHash", "sha", "renderedSha256", "img"));assertEquals("PASS",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(binding),c,cn.bidcheck.compat.Java8Api.mapOf("visualObservations", cn.bidcheck.compat.Java8Api.listOf(observed))).evaluate(r).status());assertEquals("SUBJECT_RELATION_UNPROVEN",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(),c,cn.bidcheck.compat.Java8Api.mapOf("visualObservations", cn.bidcheck.compat.Java8Api.listOf(observed))).evaluate(r).gaps().get(0).code());}
    @Test void visualMultipleApplicableMembersNeedAllObservations(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("协议书\n甲公司、乙公司为联合体成员")));Fact a=fact("RELATION","甲公司","角色","联合体成员","","",cn.bidcheck.compat.Java8Api.mapOf("object", "联合体成员"),c),b=fact("RELATION","乙公司","角色","联合体成员","","",cn.bidcheck.compat.Java8Api.mapOf("object", "联合体成员"),c);Rule r=new Rule("r","协议各成员盖章","VISUAL","联合体成员","seal","","","",cn.bidcheck.compat.Java8Api.mapOf("documentType", "协议书"),"各成员盖章","",cn.bidcheck.compat.Java8Api.listOf());Map<String,Object> observed=linked("id","v","obligationId","r","documentId","bid","location",1,"locationType","PAGE","imageHash","img","type","SEAL","observedValue","甲公司","readability","CLEAR","sourceBbox",cn.bidcheck.compat.Java8Api.listOf(1, 1, 20, 20),"source",cn.bidcheck.compat.Java8Api.mapOf("documentHash", "sha", "renderedSha256", "img"));assertEquals("UNDETERMINED",new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(a, b),c,cn.bidcheck.compat.Java8Api.mapOf("visualObservations", cn.bidcheck.compat.Java8Api.listOf(observed))).evaluate(r).status());}
    @Test void externalRoleIsNotAQueryableCompanyWithoutIdentityProof(){EvidenceCorpus c=new EvidenceCorpus(cn.bidcheck.compat.Java8Api.listOf(doc("投标资料")));Rule r=rule("EXTERNAL","投标人","listed","false",cn.bidcheck.compat.Java8Api.mapOf("externalType", "BLACKLIST"));RuleEvaluator evaluator=new RuleEvaluator(cn.bidcheck.compat.Java8Api.listOf(),c,cn.bidcheck.compat.Java8Api.mapOf());assertTrue(evaluator.resolvedSubjects(r).isEmpty());assertEquals("SUBJECT_RELATION_UNPROVEN",evaluator.evaluate(r).gaps().get(0).code());}
    @Test void numericComparisonCannotOmitExplicitTaxBasis(){Rule missing=new Rule("r","报价","NUMBER","","price","<=","100","万元",cn.bidcheck.compat.Java8Api.mapOf(),"不含税报价不超过100万元","",cn.bidcheck.compat.Java8Api.listOf());assertNotNull(RequirementGrounding.issue(missing));Rule exact=new Rule("r","报价","NUMBER","","price","<=","100","万元",cn.bidcheck.compat.Java8Api.mapOf("taxBasis", "不含税"),missing.sourceQuote(),"",cn.bidcheck.compat.Java8Api.listOf());assertNull(RequirementGrounding.issue(exact));}
}
